package com.bank.stability.monitor;

import org.springframework.stereotype.Component;
import lombok.extern.slf4j.Slf4j;
import java.util.Map;

@Component
@Slf4j
public class LeaderChurnMonitor {

    // Alert when leader election rate or imbalance indicates instability.
    public void evaluate(Map<String, Integer> leaderCountPerBroker, int electionsLastMinute) {
        int max = leaderCountPerBroker.values().stream().mapToInt(i -> i).max().orElse(0);
        int min = leaderCountPerBroker.values().stream().mapToInt(i -> i).min().orElse(0);
        if (electionsLastMinute > 5) {
            log.error("High leader election rate {}/min — cluster instability, investigate root cause",
                    electionsLastMinute);
        }
        if (max - min > Math.max(1, max / 4)) {
            log.warn("Leader imbalance: max={} min={} across brokers (hotspot risk)", max, min);
        } else {
            log.info("Leadership balanced: max={} min={}, elections/min={}", max, min, electionsLastMinute);
        }
    }
}
