// ─── File: demo/LeaderChurnDemo.java ───
package com.bank.stability.demo;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class LeaderChurnDemo {

    private static final Logger log = Logger.getLogger(LeaderChurnDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        log.info("=== Unstable: broker-2 flapping (long GC pauses) ===");
        Broker b2 = new Broker("broker-2");
        PartitionLeadership lead = new PartitionLeadership("broker-2"); // b2 is leader for settle-*
        ClientImpact impact = new ClientImpact();
        for (int t = 0; t < 10; t++) {
            b2.flap();                                   // evicted then re-added
            lead.leaderMoved(impact);                    // leader bounces each flap
        }
        impact.report("UNSTABLE", log);

        log.info("=== Stabilized: fixed GC, disabled aggressive auto-rebalance ===");
        Broker b2fixed = new Broker("broker-2");
        b2fixed.fixGarbageCollection();
        PartitionLeadership stable = new PartitionLeadership("broker-2");
        ClientImpact impact2 = new ClientImpact();
        for (int t = 0; t < 10; t++) {
            if (b2fixed.isHealthy()) {
                // no flap, no leader move
            } else {
                stable.leaderMoved(impact2);
            }
        }
        impact2.report("STABILIZED", log);
    }
}

// ─── Would be in Broker.java in a real project ───
class Broker {
    final String name;
    private boolean healthy = false; // starts unstable in the demo
    private boolean gcFixed = false;
    Broker(String name) { this.name = name; }

    void flap() { healthy = false; } // long GC pause -> missed heartbeat -> evicted
    void fixGarbageCollection() { gcFixed = true; healthy = true; }
    boolean isHealthy() { return gcFixed && healthy; }
}

// ─── Would be in PartitionLeadership.java in a real project ───
class PartitionLeadership {
    private final String preferredLeader;
    PartitionLeadership(String preferredLeader) { this.preferredLeader = preferredLeader; }

    void leaderMoved(ClientImpact impact) {
        impact.notLeaderErrors += 50;     // clients hitting old leader
        impact.metadataRefreshes += 50;
        impact.retries += 50;
        impact.lagBumpMsgs += 2000;       // stall during transition
        impact.coordinationOps += 10;     // metadata + ISR updates
        impact.isrShrinkEvents += 1;      // follower may fall out during churn
    }
}

// ─── Would be in ClientImpact.java in a real project ───
class ClientImpact {
    long notLeaderErrors, metadataRefreshes, retries, lagBumpMsgs, coordinationOps, isrShrinkEvents;

    void report(String label, Logger log) {
        if (isrShrinkEvents > 3) {
            log.severe(label + ": NOT_LEADER=" + notLeaderErrors + " refreshes=" + metadataRefreshes
                    + " retries=" + retries + " lagBump=" + lagBumpMsgs + " coordOps=" + coordinationOps
                    + " ISR_SHRINK=" + isrShrinkEvents + " (DURABILITY AT RISK)");
        } else {
            log.info(label + ": NOT_LEADER=" + notLeaderErrors + " refreshes=" + metadataRefreshes
                    + " retries=" + retries + " lagBump=" + lagBumpMsgs + " coordOps=" + coordinationOps
                    + " ISR_SHRINK=" + isrShrinkEvents + " (stable)");
        }
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    public String format(LogRecord r) {
        return String.format("[%1$tF %1$tT] [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
